foreach([10,100,1000,10000] as $n){$start=microtime(true);for($offset=$previous;$offset<$n;$offset+=500){$batch=[];for($i=$offset;$i<min($offset+500,$n);$i++)$batch[]=['external_id'=>'benchmark-'.$i,'reviewer'=>'Sample benchmark '.$i,'rating'=>5,'content'=>'Synthetic performance fixture, not a real customer review. বাংলা العربية.','review_date'=>'2024-01-01','source_name'=>'Synthetic benchmark'];$r=Reviews::import($batch,$location);if($r['errors'])throw new RuntimeException('Fixture import failed');}$import=(microtime(true)-$start)*1000;$previous=$n;
